/** Captures the (method, params) a high-level SorobanServer call assembles,
 *  so request/filter construction can be asserted without a live RPC.
 *  File scope (not nested) so moc parses it cleanly. */
class CapturingSorobanServer : public SorobanServer
{
public:
    CapturingSorobanServer() : SorobanServer(QUrl("http://127.0.0.1:1/")) {}
    QString lastMethod;
    QJsonObject lastParams;
    QJsonValue sendRequest(const QString& method, const QJsonValue& params) override {
        lastMethod = method;
        lastParams = params.toObject();
        // Minimal valid getEvents result so GetEventsResponse::fromJson is happy.
        QJsonObject resp;
        resp.insert("events", QJsonArray());
        resp.insert("latestLedger", 200);
        resp.insert("oldestLedger", 150);
        resp.insert("latestLedgerCloseTime", QStringLiteral("1700000200"));
        resp.insert("oldestLedgerCloseTime", QStringLiteral("1700000150"));
        resp.insert("cursor", QStringLiteral("c"));
        return resp;
    }
};

/**
 * Checks of what the Soroban RPC readers accept and refuse, shared by the
 * sorobanrpc tests: a real answer is edited field by field, and each edit
 * must be refused with an error that names the method and the field.
 */
struct RpcAnswerChecks
{
    /** The JSON-RPC `result` of a whole answer, as SorobanServer reads it. */
    static QJsonObject resultOf(const QByteArray& answer)
    {
        return SorobanServer::parseRpcResult(answer).toObject();
    }

    /** `node` with the field at `path` (a number steps into an array) set to
     *  `value`, or taken out for an undefined value. */
    static QJsonValue edited(const QJsonValue& node, QStringList path, const QJsonValue& value)
    {
        if (path.isEmpty())
            return value;
        const QString step = path.takeFirst();
        bool isIndex = false;
        const int index = step.toInt(&isIndex);
        if (isIndex) {
            QJsonArray array = node.toArray();
            if (index < array.size())
                array.replace(index, edited(array.at(index), path, value));
            else
                array.append(edited(QJsonValue(), path, value));
            return array;
        }
        QJsonObject object = node.toObject();
        const QJsonValue child = edited(object.value(step), path, value);
        if (child.isUndefined())
            object.remove(step);
        else
            object.insert(step, child);
        return object;
    }

    static QJsonObject edited(const QJsonObject& root, const QString& path, const QJsonValue& value)
    {
        return edited(QJsonValue(root), path.split(QLatin1Char('.')), value).toObject();
    }

    /** The name an error gives the field at `path`: "events.0.ledger" is
     *  "events[0].ledger". */
    static QString fieldName(const QString& path)
    {
        QString out;
        for (const QString& step : path.split(QLatin1Char('.'))) {
            bool isIndex = false;
            step.toInt(&isIndex);
            if (isIndex)
                out += QLatin1Char('[') + step + QLatin1Char(']');
            else
                out += (out.isEmpty() ? QString() : QStringLiteral(".")) + step;
        }
        return out;
    }

    /** What reading threw (a std::runtime_error), or an empty string. */
    static QString refusal(const std::function<void()>& read)
    {
        try {
            read();
        } catch (const std::runtime_error& e) {
            return QString::fromUtf8(e.what());
        }
        return QString();
    }

    static QString shown(const QJsonValue& value)
    {
        return value.isUndefined() ? QStringLiteral("(missing)")
            : QString::fromUtf8(QJsonDocument(QJsonArray{ value }).toJson(QJsonDocument::Compact));
    }

    typedef QPair<QString, QJsonValue> Case;

    /**
     * The real answer is read; each case (a field and what it is set to, or
     * missing) is refused with an error that names the method and the field.
     * Returns what went wrong, or an empty string.
     */
    static QString checkRefusals(const QString& method, const QJsonObject& real,
                                 const QList<Case>& cases,
                                 const std::function<void(const QJsonObject&)>& read)
    {
        const QString control = refusal([&] { read(real); });
        if (!control.isEmpty())
            return QStringLiteral("the real answer was refused: ") + control;
        const QString prefix = QStringLiteral("Soroban RPC: %1 answered").arg(method);
        for (const Case& c : cases) {
            const QString message = refusal([&] { read(edited(real, c.first, c.second)); });
            if (!message.startsWith(prefix) || !message.contains(fieldName(c.first)))
                return QStringLiteral("%1 = %2 gave \"%3\"").arg(c.first, shown(c.second), message);
        }
        return QString();
    }

    static QJsonValue missing() { return QJsonValue(QJsonValue::Undefined); }

    /** What no uint32 the RPC sends as a JSON integer may be. */
    static QList<Case> badUint32(const QString& path)
    {
        return { { path, QStringLiteral("12") }, { path, QStringLiteral("abc") }, { path, 1.5 },
                 { path, -1 }, { path, qint64(4294967296LL) }, { path, true },
                 { path, QJsonValue(QJsonValue::Null) }, { path, missing() } };
    }

    /** ... nor a field the SDK keeps as a qint32. */
    static QList<Case> badInt32(const QString& path)
    {
        return { { path, QStringLiteral("1") }, { path, 1.5 }, { path, -1 },
                 { path, qint64(2147483648LL) }, { path, QJsonValue(QJsonValue::Null) },
                 { path, missing() } };
    }

    /** ... nor an int64 the RPC sends as a JSON integer. */
    static QList<Case> badInt64Number(const QString& path)
    {
        return { { path, QStringLiteral("1790624532") }, { path, 1790624532.5 }, { path, -1 },
                 { path, 1e19 }, { path, QJsonValue(QJsonValue::Null) }, { path, missing() } };
    }

    /** ... nor a 64-bit value the RPC sends as a decimal string, whose first
     *  value out of range is `tooBig`. */
    static QList<Case> badDecimal(const QString& path, const QString& tooBig)
    {
        return { { path, 12 }, { path, QStringLiteral("abc") }, { path, QStringLiteral("-1") },
                 { path, QStringLiteral("1.5") }, { path, QStringLiteral(" 12") },
                 { path, QStringLiteral("12 ") }, { path, QStringLiteral("+12") },
                 { path, QStringLiteral("0x10") }, { path, QString() }, { path, tooBig },
                 { path, QJsonValue(QJsonValue::Null) }, { path, missing() } };
    }

    static QList<Case> badHash(const QString& path)
    {
        return { { path, QStringLiteral("abc") }, { path, QString(64, QLatin1Char('g')) },
                 { path, QString(63, QLatin1Char('a')) }, { path, QString(65, QLatin1Char('a')) },
                 { path, QString() }, { path, 12 }, { path, QJsonValue(QJsonValue::Null) },
                 { path, missing() } };
    }

    /** What no base64 XDR may be: not base64, not whole 4-byte words, empty,
     *  or another spelling of whole words than the canonical one the RPC
     *  writes: without its padding, or with the unused bits of its last
     *  character set (those used to be read). */
    static QList<Case> badXdr(const QString& path)
    {
        return { { path, QStringLiteral("AAAA!AAA") }, { path, QStringLiteral("AAAAAAAA ") },
                 { path, QStringLiteral("AAAA") }, { path, QString() }, { path, 12 },
                 { path, QStringLiteral("AAAAAA") }, { path, QStringLiteral("AAAAAQ") },
                 { path, QStringLiteral("AAAAAA=") }, { path, QStringLiteral("AAAAAB==") },
                 { path, QStringLiteral("AAAAAAAAAAA") }, { path, QStringLiteral("AAAAAAAAAAB=") },
                 { path, QJsonValue(QJsonValue::Null) }, { path, missing() } };
    }

    static QList<Case> badString(const QString& path)
    {
        return { { path, 12 }, { path, true }, { path, QJsonValue(QJsonValue::Null) },
                 { path, missing() } };
    }

    static QList<Case> badBool(const QString& path)
    {
        return { { path, QStringLiteral("true") }, { path, 1 }, { path, QJsonValue(QJsonValue::Null) },
                 { path, missing() } };
    }

    static QList<Case> joined(QList<Case> a, const QList<Case>& b) { a.append(b); return a; }

};

