    // The fields are the RPC's; the event strings are base64 XDR words now
    // (they were placeholders like "DGE1", which are not base64 XDR).
    void testGetTransactionRichFields()
    {
        QByteArray json = "{"
            "  \"status\": \"SUCCESS\","
            "  \"txHash\": \"7fd9d6aaabbf98c3077ec572c940e1f709253f7478b46b214aacf6fe4db1b850\","
            "  \"latestLedger\": 100,"
            "  \"latestLedgerCloseTime\": \"1790623262\","
            "  \"oldestLedger\": 1,"
            "  \"oldestLedgerCloseTime\": \"1790018467\","
            "  \"applicationOrder\": 1,"
            "  \"feeBump\": true,"
            "  \"envelopeXdr\": \"AAAAAg==\","
            "  \"resultXdr\": \"AAAAAw==\","
            "  \"resultMetaXdr\": \"AAAABA==\","
            "  \"ledger\": 95,"
            "  \"createdAt\": \"1700000000\","
            "  \"diagnosticEventsXdr\": [ \"AAAAAQ==\", \"AAAAAg==\" ],"
            "  \"events\": {"
            "    \"diagnosticEventsXdr\": [ \"AAAAEA==\" ],"
            "    \"transactionEventsXdr\": [ \"AAAAIA==\", \"AAAAIQ==\" ],"
            "    \"contractEventsXdr\": [ [ \"AAAAMA==\", \"AAAAMQ==\" ], [ \"AAAAQA==\" ] ]"
            "  }"
            "}";
        GetTransactionResponse r = GetTransactionResponse::fromJson(parseObj(json));

        QCOMPARE(static_cast<int>(r.getStatus()),
                 static_cast<int>(GetTransactionResponse::Status::SUCCESS));
        QVERIFY(r.getFeeBump());
        QCOMPARE(r.getDiagnosticEventsXdr().size(), 2);
        QCOMPARE(r.getDiagnosticEventsXdr().at(0), QString("AAAAAQ=="));
        QCOMPARE(r.getDiagnosticEventsXdr().at(1), QString("AAAAAg=="));

        GetTransactionResponse::Events ev = r.getEvents();
        QCOMPARE(ev.diagnosticEventsXdr.size(), 1);
        QCOMPARE(ev.diagnosticEventsXdr.at(0), QString("AAAAEA=="));
        QCOMPARE(ev.transactionEventsXdr.size(), 2);
        QCOMPARE(ev.transactionEventsXdr.at(1), QString("AAAAIQ=="));
        QCOMPARE(ev.contractEventsXdr.size(), 2);
        QCOMPARE(ev.contractEventsXdr.at(0).size(), 2);
        QCOMPARE(ev.contractEventsXdr.at(0).at(1), QString("AAAAMQ=="));
        QCOMPARE(ev.contractEventsXdr.at(1).size(), 1);
        QCOMPARE(ev.contractEventsXdr.at(1).at(0), QString("AAAAQA=="));

        // With no flat list, the nested diagnostics stand in for it.
        const GetTransactionResponse nested = GetTransactionResponse::fromJson(
            edited(parseObj(json), QStringLiteral("diagnosticEventsXdr"), missing()));
        QCOMPARE(nested.getDiagnosticEventsXdr(), QStringList{ QStringLiteral("AAAAEA==") });
    }

    static QJsonObject parseObj(const QByteArray& json)
    {
        return QJsonDocument::fromJson(json).object();
    }

