    /**
     * Every field js-stellar-sdk 17.1.0 (rpc parseRawTransactions and the
     * page) and py-stellar-sdk 14.1.0 (soroban_rpc.GetTransactionsResponse)
     * read of a real getTransactions answer is read here, with the values
     * both read. js decodes each XDR and writes it back to the very text sent
     * (compared here with the answer, and by its length); the event lists are
     * in the order js and py give them, contractEventsXdr one list per
     * operation. js's returnValue is undefined for all three (meta v4 with
     * sorobanMeta null): hasReturnValue() is false.
     */
    void testGetTransactionsReadsEveryFieldJsAndPyRead()
    {
        struct Tx {
            GetTransactionResponse::Status status; QString txHash; quint32 ledger; QString createdAt;
            qint32 applicationOrder; bool feeBump; int envelopeXdrSize; QString resultXdr;
            int resultMetaXdrSize; QStringList diagnosticEventsXdr; QList<int> transactionEventSizes;
            QList<int> contractEventsPerOperation;
        };
        const QList<Tx> want = {
            { GetTransactionResponse::Status::SUCCESS,
              QStringLiteral("27d23a6182871c2a7462847332e12cf5e8fde22a2ce51fe58f112d57415c11b3"),
              4919629, QStringLiteral("1790621732"), 1, false, 428,
              QStringLiteral("AAAAAAAAAGQAAAAAAAAAAQAAAAAAAAAAAAAAAAAAAAA="), 1408,
              QStringList(),
              QList<int>{ 176 }, QList<int>{ 1 } },
            { GetTransactionResponse::Status::FAILED,
              QStringLiteral("7cf7e5deb32bc8d3f71a27f29a9363db6a26660af527a81c7c06d8c00bf73bf2"),
              4919629, QStringLiteral("1790621732"), 2, false, 352,
              QStringLiteral("AAAAAAAAAGT/////AAAAAQAAAAAAAAAB/////gAAAAA="), 616,
              QStringList(),
              QList<int>{ 176 }, QList<int>{  } },
            { GetTransactionResponse::Status::FAILED,
              QStringLiteral("33e6a4f589073abaee8ce4e4fad84ecd49a49d0aa5af0bd1a1da6b21a9c4532e"),
              4919629, QStringLiteral("1790621732"), 3, false, 432,
              QStringLiteral("AAAAAAAAAGT/////AAAAAQAAAAAAAAAB/////gAAAAA="), 616,
              QStringList(),
              QList<int>{ 176 }, QList<int>{  } }
        };
        const QJsonObject real = resultOf(realGetTransactions());
        const QJsonArray sent = real.value("transactions").toArray();
        const GetTransactionsResponse r = GetTransactionsResponse::fromJson(real);
        QCOMPARE(r.getLatestLedger(), quint32(4920189));
        QCOMPARE(r.getLatestLedgerCloseTime(), QString("1790624532"));
        QCOMPARE(r.getOldestLedger(), quint32(4799230));
        QCOMPARE(r.getOldestLedgerCloseTime(), QString("1790019737"));
        QCOMPARE(r.getCursor(), QString("21129645663465473"));
        QCOMPARE(r.getTransactions().size(), want.size());
        for (int i = 0; i < want.size(); ++i) {
            const GetTransactionResponse& got = r.getTransactions().at(i);
            const Tx& w = want.at(i);
            const QJsonObject tx = sent.at(i).toObject();
            const QJsonObject events = tx.value("events").toObject();
            QCOMPARE(status(got.getStatus()), status(w.status));
            QCOMPARE(got.getTxHash(), w.txHash);
            QCOMPARE(got.getLedger(), w.ledger);
            QCOMPARE(got.getCreatedAt(), w.createdAt);
            QCOMPARE(got.getApplicationOrder(), w.applicationOrder);
            QCOMPARE(got.getFeeBump(), w.feeBump);
            QCOMPARE(got.getEnvelopeXdr(), tx.value("envelopeXdr").toString());
            QCOMPARE(got.getEnvelopeXdr().size(), w.envelopeXdrSize);
            QCOMPARE(got.getResultXdr(), w.resultXdr);
            QCOMPARE(got.getResultMetaXdr(), tx.value("resultMetaXdr").toString());
            QCOMPARE(got.getResultMetaXdr().size(), w.resultMetaXdrSize);
            QCOMPARE(got.getDiagnosticEventsXdr(), w.diagnosticEventsXdr);
            QVERIFY(!got.hasReturnValue());
            const GetTransactionResponse::Events ev = got.getEvents();
            QCOMPARE(ev.transactionEventsXdr.size(), w.transactionEventSizes.size());
            for (int k = 0; k < w.transactionEventSizes.size(); ++k) {
                QCOMPARE(ev.transactionEventsXdr.at(k),
                         events.value("transactionEventsXdr").toArray().at(k).toString());
                QCOMPARE(ev.transactionEventsXdr.at(k).size(), w.transactionEventSizes.at(k));
            }
            QCOMPARE(ev.contractEventsXdr.size(), w.contractEventsPerOperation.size());
            for (int op = 0; op < w.contractEventsPerOperation.size(); ++op) {
                const QJsonArray group = events.value("contractEventsXdr").toArray().at(op).toArray();
                QCOMPARE(ev.contractEventsXdr.at(op).size(), w.contractEventsPerOperation.at(op));
                for (int k = 0; k < group.size(); ++k)
                    QCOMPARE(ev.contractEventsXdr.at(op).at(k), group.at(k).toString());
            }
        }
    }

