    /**
     * Every field js-stellar-sdk 17.1.0 (getVersionInfo, the RPC's result as
     * sent) and py-stellar-sdk 14.1.0 (soroban_rpc.GetVersionInfoResponse)
     * read of a real getVersionInfo answer, with the values both read:
     * version, commitHash, buildTimestamp, captiveCoreVersion and
     * protocolVersion. Only the camelCase names are read, as py reads them:
     * the snake_case ones js's typings also declare (commit_hash,
     * build_timestamp, captive_core_version, protocol_version) are ignored
     * next to them, as is a field nobody knows, and an answer with only
     * those is refused, as py refuses it (js would hand it on with the
     * camelCase fields undefined). An empty string is read as empty, as py
     * reads it.
     */
    void testGetVersionInfoReadsWhatJsAndPyRead()
    {
        const QJsonObject real = resultOf(realGetVersionInfo());
        const auto fields = [](const GetVersionInfoResponse& v) {
            return QStringList{ v.getVersion(), v.getCommitHash(), v.getBuildTimestamp(),
                                v.getCaptiveCoreVersion(), QString::number(v.getProtocolVersion()) };
        };
        const QStringList expected{ "29.0.0-b2b701685c79aee17fe4eb22dbd08a5dfd11594d",
                                    "b2b701685c79aee17fe4eb22dbd08a5dfd11594d", "2026-09-22T14:52:44",
                                    "stellar-core 29.0.0 (4eb83337380a29ad0907f4e32196ce97b8dc7649)", "28" };
        QCOMPARE(fields(GetVersionInfoResponse::fromJson(real)), expected);

        QJsonObject both = real;
        both.insert("commit_hash", QStringLiteral("0123"));
        both.insert("build_timestamp", QStringLiteral("2024-01-01T00:00:00"));
        both.insert("captive_core_version", QStringLiteral("stellar-core 21.0.0"));
        both.insert("protocol_version", 21);
        both.insert("unknownField", QJsonObject{ { "a", 1 } });
        QCOMPARE(fields(GetVersionInfoResponse::fromJson(both)), expected);

        QJsonObject empty = real;
        for (const char* key : { "version", "commitHash", "buildTimestamp", "captiveCoreVersion" })
            empty.insert(QString::fromLatin1(key), QStringLiteral(""));
        QCOMPARE(fields(GetVersionInfoResponse::fromJson(empty)), (QStringList{ "", "", "", "", "28" }));

        QJsonObject snakeOnly = both;
        for (const char* key : { "commitHash", "buildTimestamp", "captiveCoreVersion", "protocolVersion" })
            snakeOnly.remove(QString::fromLatin1(key));
        const QString message = refusal([&] { GetVersionInfoResponse::fromJson(snakeOnly); });
        QVERIFY2(message.startsWith(QLatin1String("Soroban RPC: getVersionInfo answered")), qPrintable(message));
        QVERIFY2(message.contains(QLatin1String("commitHash")), qPrintable(message));
    }

