    /**
     * getTransaction: a missing or unknown status used to read as NOT_FOUND,
     * so pollTransaction polled on until its timeout for an answer it could
     * not read; now the answer is refused, and pollTransaction with it.
     */
    void testGetTransactionRefusesAMissingOrUnknownStatus()
    {
        const QJsonObject real = resultOf(realGetTransactionNotFound());
        for (const QJsonValue& bad : { missing(), QJsonValue(QJsonValue::Null), QJsonValue(QString()),
                                        QJsonValue(QStringLiteral("not_found")), QJsonValue(QStringLiteral("PENDING")),
                                        QJsonValue(QStringLiteral("SUCCESS ")), QJsonValue(0), QJsonValue(true) }) {
            const QString message = refusal([&] { GetTransactionResponse::fromJson(edited(real, QStringLiteral("status"), bad)); });
            QVERIFY2(message.startsWith(QStringLiteral("Soroban RPC: getTransaction answered")) && message.contains(QStringLiteral("status")),
                     qPrintable(shown(bad) + QStringLiteral(": ") + message));
        }

        // pollTransaction ends with the refusal instead of polling on.
        class AnsweringServer : public SorobanServer
        {
        public:
            AnsweringServer() : SorobanServer(QUrl(QStringLiteral("http://127.0.0.1:1/"))) {}
            QJsonObject answer;
            int asked = 0;
            QJsonValue sendRequest(const QString&, const QJsonValue&) override { ++asked; return answer; }
        };
        AnsweringServer server;
        server.answer = edited(real, QStringLiteral("status"), QStringLiteral("PENDING"));
        QElapsedTimer clock;
        clock.start();
        const QString message = refusal([&] {
            server.pollTransaction(real.value("txHash").toString(), 60000, 10);
        });
        QVERIFY2(message.contains(QStringLiteral("status")), qPrintable(message));
        QCOMPARE(server.asked, 1);
        QVERIFY(clock.elapsed() < 30000);
    }

    /** getTransaction: every other field as the RPC sends it. Missing or
     *  non-numeric numbers used to read as 0, and anything was taken for a
     *  hash or XDR. */
    void testGetTransactionRefusesWhatTheRpcDoesNotSend()
    {
        const QString i64Over = QStringLiteral("9223372036854775808");
        QList<Case> always;
        always.append(badHash(QStringLiteral("txHash")));
        always.append(badUint32(QStringLiteral("latestLedger")));
        always.append(badUint32(QStringLiteral("oldestLedger")));
        always.append(badDecimal(QStringLiteral("latestLedgerCloseTime"), i64Over));
        always.append(badDecimal(QStringLiteral("oldestLedgerCloseTime"), i64Over));
        always.append(badInt32(QStringLiteral("applicationOrder")));
        always.append(badBool(QStringLiteral("feeBump")));
        always.append(badUint32(QStringLiteral("ledger")));
        always.append(badDecimal(QStringLiteral("createdAt"), i64Over));
        always.append({ QStringLiteral("events"), QJsonArray() });

        QList<Case> found = always;
        for (const char* key : { "envelopeXdr", "resultXdr", "resultMetaXdr" })
            found.append(badXdr(QString::fromLatin1(key)));
        found.append({ QStringLiteral("events.transactionEventsXdr.0"), QStringLiteral("AAAA!AAA") });
        found.append({ QStringLiteral("events.contractEventsXdr"), QJsonObject() });
        QJsonArray badGroup; badGroup.append(QJsonArray{ QStringLiteral("AAAAAQ=="), 12 });
        found.append({ QStringLiteral("events.contractEventsXdr"), badGroup });
        found.append({ QStringLiteral("diagnosticEventsXdr"), QStringLiteral("AAAAAQ==") });

        auto read = [](const QJsonObject& o) { GetTransactionResponse::fromJson(o); };
        QString problem = checkRefusals(QStringLiteral("getTransaction"), resultOf(realGetTransactionFailed()), found, read);
        QVERIFY2(problem.isEmpty(), qPrintable(problem));
        // The contract call's own event lists.
        found.append({ QStringLiteral("diagnosticEventsXdr.3"), QStringLiteral("AAAA") });
        found.append({ QStringLiteral("events.contractEventsXdr.0"), QStringLiteral("AAAAAQ==") });
        problem = checkRefusals(QStringLiteral("getTransaction"), resultOf(realGetTransactionSuccess()), found, read);
        QVERIFY2(problem.isEmpty(), qPrintable(problem));
        // A transaction not found comes without the XDR, but with every number.
        QList<Case> notFound = always;
        notFound.append({ QStringLiteral("envelopeXdr"), QStringLiteral("AAAA") });
        problem = checkRefusals(QStringLiteral("getTransaction"), resultOf(realGetTransactionNotFound()), notFound, read);
        QVERIFY2(problem.isEmpty(), qPrintable(problem));
    }

